class Solution:
    def maxVowels(self, s: str, k: int) -> int:
        
        res=0
        n=len(s)
        vowels = "aeiou"
        for i in range(k,n+1):
            count=0
            window = s[i-k:i]
            for char in window:
                if char in vowels:
                    count+=1

            res=max(count,res)



        return res




a=Solution()
s = "abciiidef"
k = 3
print(a.maxVowels(s,k))

s = "aeiou"
k = 2
print(a.maxVowels(s,k))

s = "leetcode"
k = 3
print(a.maxVowels(s,k))

s=""
k=50436
print(a.maxVowels(s,k))